function testCondition(c,s,year){const why=[];if(!c)return why;for(const[k,v]of Object.entries(c.minStats||{}))if(!STATS.includes(k)||s.stats[k]<v)why.push(k+'未达到'+v);for(const[k,v]of Object.entries(c.maxStats||{}))if(!STATS.includes(k)||s.stats[k]>v)why.push(k+'高于'+v);if(c.flagsAll?.some(f=>!s.flags.includes(f)))why.push('缺少必要路径标记');if(c.flagsAny?.length&&!c.flagsAny.some(f=>s.flags.includes(f)))why.push('未进入所需路径');if(c.flagsNone?.some(f=>s.flags.includes(f)))why.push('当前路径已排除');if(c.projectStatus?.length&&!c.projectStatus.includes(s.project.status))why.push('项目阶段不适用');if(c.locations?.length&&!c.locations.includes(s.location))why.push('地点不适用');if(Number.isInteger(c.minPeople)&&s.people.length<c.minPeople)why.push('尚无足够同行者');if(Number.isInteger(c.maxPeople)&&s.people.length>c.maxPeople)why.push('同行者数量已超条件');if(Number.isInteger(c.minAge)&&year-2000<c.minAge)why.push('未到适用年龄');if(Number.isInteger(c.maxAge)&&year-2000>c.maxAge)why.push('超过适用年龄');if(Number.isInteger(c.minYear)&&year<c.minYear)why.push('未到适用年份');if(Number.isInteger(c.maxYear)&&year>c.maxYear)why.push('超过适用年份');return why;}
