function fillDeep(value,state,year){if(typeof value==='string')return fill(value,state,year);if(Array.isArray(value))return value.map(v=>fillDeep(v,state,year));if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,fillDeep(v,state,year)]));return value;}
