function apply(run,change,year,origin){const before=clone(run.stats),actual={};for(const k of STATS){const effect=Number(change.effects?.[k]||0);assert(Number.isFinite(effect)&&Math.abs(effect)<=40,'状态效果无效。');const scale=effect>=0?clamp((100-run.stats[k])/50,.12,1.6):clamp(run.stats[k]/50,.12,1.6);run.stats[k]=round(clamp(run.stats[k]+effect*scale,0,100));actual[k]=round(run.stats[k]-before[k]);}const set=change.set||{};for(const field of ['location','vocation'])if(set[field]!==undefined){assert(textValue(set[field],100),'世界状态文字过长。');run[field]=set[field];}if(set.projectName!==undefined){assert(textValue(set.projectName,120),'项目名过长。');run.project.name=fill(set.projectName,run,year);run.project.startedYear=year;}if(set.projectStatus!==undefined){assert(textValue(set.projectStatus,60),'项目状态无效。');run.project.status=set.projectStatus;}for(const f of change.removeFlags||[])run.flags=run.flags.filter(x=>x!==f);for(const f of change.addFlags||[]){assert(textValue(f,80),'路径标记无效。');if(!run.flags.includes(f))run.flags.push(f);}let delta=Math.trunc(change.peopleDelta||0);assert(Number.isFinite(delta)&&Math.abs(delta)<=5,'同行者变化超界。');while(delta>0&&run.people.length<16){const id='person-'+year+'-'+hash(origin+'|'+run.people.length).toString(16);if(!run.people.some(p=>p.id===id))run.people.push({id,label:'同行者'+(run.people.length+1),role:'collaborator',closeness:40,metYear:year});delta--;}while(delta<0){const at=run.people.findIndex(p=>p.role!=='partner');if(at<0)break;run.people.splice(at,1);delta++;}if((change.addFlags||[]).includes('partner_active')&&!run.people.some(p=>p.role==='partner')){if(run.people.length>=16)run.people.splice(0,1);run.people.push({id:'partner-'+year,label:'亲密同行者',role:'partner',closeness:50,metYear:year});}if((change.removeFlags||[]).includes('partner_active'))for(const p of run.people)if(p.role==='partner')p.role='past_partner';return actual;}
function eventNarrative(e,v,state,year,before,after,chosen){let text=fill(v.text,state,year);if(before.location!==after.location)text+=' 这件事之后，你把下一段日常转到'+after.location+'。';if(before.project.status!==after.project.status)text+=' 你把手边的作品重新安排为'+statusLabel(after.project.status)+'。';return{title:fill(v.title||e.title,state,year),text,explanation:`本次可用场景的编辑选取权重${round(chosen.probability*100)}%；基础${chosen.baseWeight}×主题${chosen.themeFactor}×次要节奏${chosen.astroFactor}×实际状态${chosen.stateFactor}×重心${chosen.focusFactor}×重复抑制${chosen.noveltyFactor}×承接${chosen.balanceFactor}，在当次合条件场景内归一化。不是紫微事件概率。`};}
