const rules=Object.freeze({version:VERSION,minYear:MIN,maxYear:MAX,factsThrough:FACTS,statsNature:'六项数值仅为游戏状态，初值是编辑设定，不是健康、能力或财富测量。',initialStats:clone(INITIAL),coefficientsNature:'定性主轴优先；场景门槛、主题系数与状态回归是公开的游戏编辑规则，不是传统斗数吉凶公式或经验统计参数。',probabilityNature:'事件目录的条件选取权重，不是经验验证的个人事件发生率。命盘与编辑指数只改变故事池的阅读侧重。',weightFormula:'weight=baseWeight×themeFactor×astroFactor×stateFactor×focusFactor×noveltyFactor×balanceFactor；不满足条件或冷却时weight=0；probability=weight/当次所有可用weight之和。先按年度强主题筛主事件，再承接实际后果或相关日常；每次抽取后先更新世界再重算。',astroFormula:'年度主轴来自本命、大限、流年主星落宫，四化三层同星叠化与命宫三方四正的定性阅读。themeFactor=主轴3.6/其余本年前四主题1.6/普通日常1；首先按主题门槛筛主事件。原始机会/阻力和六维只给0.85—1.15的次要节奏系数，不据此判吉凶或制造命定概率',themeFactors:{primary:3.6,otherAnnualTheme:1.6,ordinary:1},secondaryFactorBounds:[.85,1.15],contextMethod:'三层主星落宫、四化同星叠化、三合会照与对宫分开列证；年度主轴为逐年定性取重点，显著度只辅助找场景素材。',maintenance:'每年游戏状态向固定锚点回归13%；事件与选项正效果按剩余空间、负效果按当前数值缩放，避免长期堆满或枯竭。此为游戏维护规则，无年龄衰退或现实健康含义。',anchors:clone(ANCHORS),fictionalCharacters:{friend:'阿远（仅模拟朋友）',colleague:'小岑（仅模拟协作者）',partner:'只由明确选项建立，不预设婚育'},decisions:'通常间隔3–5年；当年实际情节触发且命理主题、世界状态匹配后才出现，不凭空弹出无关抉择。自动选择按当前重心和资源缺口给选项内部权重，不代表最佳人生建议。',boundary:'2100年周岁100只为展示边界，不生成疾病、死亡或寿命断言。',persistence:'必须使用exportRun/importRun；重复命盘与候选池不逐次保存，导入按目录和原数据重算校验。',maxSaveBytes:MAX_BYTES});
